  const onUpdateBookingStatus=(tripId:string,bookingId:string,status:BookingStatus)=>setBookingsByTrip((all)=>({...all,[tripId]:(all[tripId]??[]).map((booking)=>booking.id===bookingId?{...booking,status}:booking)}));
