  const onCreateTrip=(input:TripInput)=>{const id=crypto.randomUUID();const generated=generateDays(input.startDate,input.endDate);const next:Trip={id,name:input.name,dates:`${input.startDate} → ${input.endDate}`,startDate:input.startDate,endDate:input.endDate,duration:generated.length,route:'Your route is ready to take shape',countries:[],status:'Idea',budget:input.budget,planned:0,paid:0,progress:15,travellers:Array.from({length:input.travellers},(_,i)=>i===0?userName:`Traveller ${i+1}`),cover:'new'};setTrips((items)=>[next,...items]);setDaysByTrip((all)=>({...all,[id]:generated.map((day)=>({id:`${id}-day-${day.dayNumber}`,number:day.dayNumber,date:day.date,title:'Open day',segmentId:'',events:[]}))}));setSegmentsByTrip((all)=>({...all,[id]:[]}));void fetch('/api/trips',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({...input,id})});setModal(null)};
